1153		if r := got.Results[1]; !r.OK || !r.Changed || r.Revision != 1 || r.Sequence != 11 {
1154			t.Fatalf("result 1: %+v", r)
1155		}
1156		if r := got.Results[2]; !r.OK || !r.Changed || r.Revision != 1 || r.Sequence != 12 {
1157			t.Fatalf("result 2: %+v", r)
1158		}
1159		if r := got.Results[3]; !r.OK || !r.Changed || r.Revision != 1 || r.Sequence != 13 {
1160			t.Fatalf("result 3: %+v", r)
1161		}
1162		// 4-5: the first two selections rotate a then b; the cursor rests on b.
1163		if r := got.Results[4]; !r.OK || r.InstanceID != "a" || r.Address != "h1:1" || r.Sequence != 11 || r.Revision != 1 {
1164			t.Fatalf("result 4: %+v", r)
1165		}
1166		if r := got.Results[5]; !r.OK || r.InstanceID != "b" || r.Address != "h2:2" || r.Sequence != 12 || r.Revision != 1 {
1167			t.Fatalf("result 5: %+v", r)
1168		}
