1177		if r := got.Results[7]; r.OK || r.Error != "no_healthy" || r.Reason == "" ||
1178			r.Revision != 2 || r.InstanceID != "" || r.Address != "" {
1179			t.Fatalf("result 7 no_healthy on empty list: %+v", r)
1180		}
