1720			{"type":"register","service":"svc","expectedRevision":1,"instances":[{"id":"a","address":"h9:9"},{"id":"b","address":"h2:2"},{"id":"c","address":"h3:3"}]},
1721			{"type":"health","service":"svc","instanceId":"b","expectedRevision":2,"sequence":14,"healthy":false,"reason":"连接拒绝"},
1722			{"type":"health","service":"svc","instanceId":"c","expectedRevision":2,"sequence":15,"healthy":false,"reason":"连接拒绝"},
1723			{"type":"health","service":"svc","instanceId":"a","expectedRevision":1,"sequence":99,"healthy":true},
1724			{"type":"select","service":"svc","expectedRevision":2,"sessionKey":"s"},
1725			{"type":"health","service":"svc","instanceId":"a","expectedRevision":2,"sequence":1,"healthy":true},
1726			{"type":"select","service":"svc","expectedRevision":2,"sessionKey":"s"},
1727			{"type":"health","service":"svc","instanceId":"b","expectedRevision":2,"sequence":16,"healthy":true},
1728			{"type":"health","service":"svc","instanceId":"c","expectedRevision":2,"sequence":17,"healthy":true},
1729			{"type":"select","service":"svc","expectedRevision":2}
1730		]}`
1731		out, code := runRegisterWith(t, input)
