1736		if err := json.Unmarshal([]byte(out), &got); err != nil {
1737			t.Fatalf("output is not JSON: %v\n%s", err, out)
1738		}
1739		// One result per request, in input order; failed items keep their slots.
1740		if len(got.Results) != 16 {
