1748			t.Fatalf("plain select: %+v", r)
1749		}
1750		// 6: the replacement resets a to unknown at its new address, revision 2.
1751		if r := got.Results[6]; !r.OK || !r.Changed || r.Revision != 2 {
1752			t.Fatalf("address replacement: %+v", r)
