// failRegister emits a top-level input error as the single JSON document on
// standard output and returns exit code 1. If that error JSON itself cannot be
// written, the delivery failure is diagnosed on standard error (standard output
// may already hold a partial document, so no second JSON is appended) and the
// exit code stays 1.
func failRegister(reason string) int {
	if err := writeRegisterOutput(os.Stdout, struct {
		Error string `json:"error"`
	}{Error: reason}); err != nil {
		reportRegisterDeliveryFailure(err)
	}
	return 1
}

// reportRegisterDeliveryFailure reports on standard error that the register
// command's JSON result could not be delivered, preserving the underlying write
// error. It never writes to standard output, which may already contain a
// partial result.
func reportRegisterDeliveryFailure(err error) {
	fmt.Fprintf(os.Stderr, "register: failed to write request results to standard output: %v\n", err)
}

// writeRegisterOutput writes v as the single indented JSON document on w.
// Standard output is dedicated to this document, so a write failure is returned
// instead of swallowed: the caller must not attempt to append another document
// after a partial write.
func writeRegisterOutput(w io.Writer, v any) error {
	enc := json.NewEncoder(w)
	enc.SetIndent("", "  ")
	return enc.Encode(v)
}

